buggy.timedelta_inf_and_overflow:
import numpy as np
import sys
try:
    from pandas import Timedelta
except Exception as e:
    print(f'Import failed: {e}')
    sys.exit(1)

# Test inf
try:
    Timedelta(np.inf)
    probe('inf_exception_type', 'none')
except OverflowError as e:
    probe('inf_exception_type', 'OverflowError')
except Exception as e:
    probe('inf_exception_type', type(e).__name__)

# Test -inf
try:
    Timedelta(-np.inf)
    probe('neg_inf_exception_type', 'none')
except OverflowError as e:
    probe('neg_inf_exception_type', 'OverflowError')
except Exception as e:
    probe('neg_inf_exception_type', type(e).__name__)

# Test 1e19 with unit='s'
try:
    Timedelta(1e19, unit='s')
    probe('round_float_overflow_exception_type', 'none')
except OverflowError as e:
    probe('round_float_overflow_exception_type', 'OverflowError')
except Exception as e:
    probe('round_float_overflow_exception_type', type(e).__name__)

# Test 10**19 with unit='s'
try:
    Timedelta(10**19, unit='s')
    probe('int_overflow_exception_type', 'none')
except OverflowError as e:
    probe('int_overflow_exception_type', 'OverflowError')
except Exception as e:
    probe('int_overflow_exception_type', type(e).__name__)

